def test_three_scalars():
    got = solution.fedavg([[0.1], [0.5], [0.9]], [100, 200, 700])
    assert abs(got[0] - 0.74) < 1e-12

def test_equal_clients():
    got = solution.fedavg([[1.0, 3.0], [3.0, 1.0]], [1, 1])
    assert abs(got[0] - 2.0) < 1e-12 and abs(got[1] - 2.0) < 1e-12

def test_two_parameters_weighted():
    got = solution.fedavg([[0.0, 2.0], [1.0, 0.0]], [1, 3])
    assert abs(got[0] - 0.75) < 1e-12 and abs(got[1] - 0.5) < 1e-12

def test_counts_mismatch():
    try:
        solution.fedavg([[0.1], [0.2]], [1])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_nonpositive_count():
    try:
        solution.fedavg([[0.1], [0.2]], [1, 0])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_ragged_models():
    try:
        solution.fedavg([[0.1], [0.2, 0.3]], [1, 1])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_no_clients():
    try:
        solution.fedavg([], [])
    except ValueError:
        return
    raise AssertionError("expected ValueError")
